import { EntityRepository, type IEntitiesRepository } from '@kinotic-ai/persistence'
import { Todo } from '../../model/Todo.js'


/**
 * Base Repository for interacting with Todo entities
 * This class was generated by the Kinotic CLI. And will be overwritten if the CLI is run again.
 */
export class BaseTodoRepository extends EntityRepository<Todo> {

  private readonly shouldValidate: boolean

  constructor(shouldValidate: boolean = true, entitiesRepository?: IEntitiesRepository) {
    super('minds', 'todo-app', 'Todo', entitiesRepository)
    this.shouldValidate = shouldValidate
  }

  protected override async beforeSaveOrUpdate(entity: Todo): Promise<Todo> {
    if (this.shouldValidate) {
      return this.validate(entity)
    } else {
      return entity
    }
  }

  protected override async beforeBulkSaveOrUpdate(entities: Todo[]): Promise<Todo[]> {
    if (this.shouldValidate) {
      const validatedEntities: Todo[] = []
      for (let entity of entities) {
        validatedEntities.push(this.validate(entity))
      }
      return validatedEntities
    } else {
      return entities
    }
  }

  validate(entity: Todo): Todo {
    let ret: any
    if (entity) {
      ret = (ret ? ret : {})
      ret.id = entity.id
      ret.title = entity.title
      ret.description = entity.description
      ret.completed = entity.completed
      ret.priority = entity.priority
      ret.dueDate = entity.dueDate
      ret.createdAt = entity.createdAt
      ret.updatedAt = entity.updatedAt
    }

    return ret
  }

}
